(args: Args) => {
  const [isOpen, setIsOpen] = useState(false)
  const buttonRef = useRef<HTMLButtonElement>(null)
  const confirmButtonRef = useRef<HTMLButtonElement>(null)
  const anchorRef = useRef<HTMLDivElement>(null)
  const closeOverlay = () => setIsOpen(false)
  const containerRef = useRef<HTMLDivElement>(null)
  useFocusTrap({
    containerRef,
    disabled: !isOpen,
  })
  return (
    <div ref={anchorRef}>
      <Button
        ref={buttonRef}
        onClick={() => {
          setIsOpen(!isOpen)
        }}
      >
        Open overlay
      </Button>
      {isOpen || args.open ? (
        <Overlay
          initialFocusRef={confirmButtonRef}
          returnFocusRef={buttonRef}
          ignoreClickRefs={[buttonRef]}
          onEscape={closeOverlay}
          onClickOutside={closeOverlay}
          width="large"
          anchorSide="inside-right"
          role="dialog"
          aria-modal="true"
          aria-label="Sample overlay"
          ref={containerRef}
        >
          <div className={classes.FullHeightContent}>
            <IconButton
              aria-label="Close"
              onClick={closeOverlay}
              icon={XIcon}
              variant="invisible"
              className={classes.CloseButtonOverlay}
            />
            <Text>Look! an overlay</Text>
          </div>
        </Overlay>
      ) : null}
    </div>
  )
}

({ anchorSide, role, open }: Args) => {
  const [isOpen, setIsOpen] = useState(false)
  const buttonRef = useRef<HTMLButtonElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const confirmButtonRef = useRef<HTMLButtonElement>(null)
  const anchorRef = useRef<HTMLDivElement>(null)
  const closeOverlay = () => setIsOpen(false)
  useFocusTrap({
    containerRef,
    disabled: !isOpen,
    initialFocusRef: confirmButtonRef,
    returnFocusRef: buttonRef,
  })
  return (
    <div ref={anchorRef}>
      <Button ref={buttonRef} onClick={() => setIsOpen(!isOpen)}>
        open overlay
      </Button>
      {isOpen || open ? (
        <Overlay
          initialFocusRef={confirmButtonRef}
          returnFocusRef={buttonRef}
          ignoreClickRefs={[buttonRef]}
          onEscape={closeOverlay}
          onClickOutside={closeOverlay}
          width="small"
          anchorSide={anchorSide}
          role={role}
          aria-modal={role === 'dialog' ? 'true' : undefined}
          aria-label={role === 'dialog' ? 'Confirmation screen' : undefined}
          ref={containerRef}
        >
          <div className={classes.DialogContent}>
            <Text>Are you sure?</Text>
            <Button variant="danger" onClick={closeOverlay}>
              Cancel
            </Button>
            <Button onClick={closeOverlay} ref={confirmButtonRef}>
              Confirm
            </Button>
          </div>
        </Overlay>
      ) : null}
    </div>
  )
}

({ right, role, open }: Args) => {
  const [isOpen, setIsOpen] = useState(false)
  const [direction, setDirection] = useState<'left' | 'right'>(
    right ? 'right' : 'left',
  )
  const buttonRef = useRef<HTMLButtonElement>(null)
  const confirmButtonRef = useRef<HTMLButtonElement>(null)
  const anchorRef = useRef<HTMLDivElement>(null)
  const closeOverlay = () => setIsOpen(false)
  const containerRef = useRef<HTMLDivElement>(null)
  useFocusTrap({
    containerRef,
    disabled: !isOpen,
  })
  return (
    <div ref={anchorRef}>
      <Button
        ref={buttonRef}
        onClick={() => {
          setIsOpen(!isOpen)
          setDirection('left')
        }}
      >
        Open left overlay
      </Button>
      <Button
        ref={buttonRef}
        onClick={() => {
          setIsOpen(!isOpen)
          setDirection('right')
        }}
        style={{
          marginTop: '8px',
        }}
      >
        Open right overlay
      </Button>
      {isOpen || open ? (
        direction === 'left' ? (
          <Overlay
            initialFocusRef={confirmButtonRef}
            returnFocusRef={buttonRef}
            ignoreClickRefs={[buttonRef]}
            onEscape={closeOverlay}
            onClickOutside={closeOverlay}
            width="auto"
            anchorSide="inside-right"
            role={role}
            aria-modal={role === 'dialog' ? 'true' : undefined}
            aria-label={role === 'dialog' ? 'Left aligned overlay' : undefined}
            ref={containerRef}
          >
            <div className={classes.ResponsiveWidthContainer}>
              <div className={classes.OverlayFullHeight}>
                <IconButton
                  aria-label="Close"
                  onClick={closeOverlay}
                  icon={XIcon}
                  variant="invisible"
                  className={classes.CloseButtonLeft}
                />
                <Text>Look! left aligned</Text>
              </div>
            </div>
          </Overlay>
        ) : (
          <Overlay
            initialFocusRef={confirmButtonRef}
            returnFocusRef={buttonRef}
            ignoreClickRefs={[buttonRef]}
            onEscape={closeOverlay}
            onClickOutside={closeOverlay}
            width="auto"
            anchorSide={'inside-left'}
            right={0}
            position="fixed"
            role={role}
            aria-modal={role === 'dialog' ? 'true' : undefined}
            aria-label={role === 'dialog' ? 'Right aligned overlay' : undefined}
            ref={containerRef}
          >
            <div className={classes.ResponsiveWidthContainer}>
              <div className={classes.OverlayFullHeight}>
                <IconButton
                  aria-label="Close"
                  onClick={closeOverlay}
                  icon={XIcon}
                  variant="invisible"
                  className={classes.CloseButtonRight}
                />
                <Text>Look! right aligned</Text>
              </div>
            </div>
          </Overlay>
        )
      ) : null}
    </div>
  )
}
